INSERT INTO missions ("id", "name", "description", "environment", "status", "startDate", "endDate", "patchUrl", "createdById", "operatorId", "createdAt", "updatedAt", "deletedAt") VALUES
  ('mission-01', 'Apollo 11 — First Lunar Landing', '8-day crewed lunar landing mission (July 16–24, 1969) aboard Saturn V SA-506, CSM Columbia, and LM Eagle with Neil Armstrong, Buzz Aldrin, and Michael Collins touching down at Mare Tranquillitatis.', 'LUNAR_BASE', 'IN_PROGRESS', (timezone('utc', now()) - interval '345600000 milliseconds'), NULL, NULL, (SELECT id FROM users WHERE email = 'elena.rodriguez@nasa.gov'), (SELECT id FROM users WHERE email = 'm.chen@nasa.gov'), (timezone('utc', now()) - interval '3888000000 milliseconds'), (timezone('utc', now()) - interval '0 milliseconds'), NULL),
  ('mission-02', 'ISS Expedition 72 — Low Earth Orbit', 'Crewed orbital science aboard the International Space Station at 415 km LEO, 51.64° inclination, and 7.66 km/s (~92.9 min orbital period) with Crew Dragon and Soyuz MS crew rotations.', 'STATION', 'IN_PROGRESS', (timezone('utc', now()) - interval '10800000 milliseconds'), NULL, NULL, (SELECT id FROM users WHERE email = 'elena.rodriguez@nasa.gov'), NULL, (timezone('utc', now()) - interval '8208000000 milliseconds'), (timezone('utc', now()) - interval '0 milliseconds'), NULL),
  ('mission-03', 'Apollo 13 — Cislunar Free-Return Abort', '6-day crewed lunar free-return mission (April 11–17, 1970) with Jim Lovell, Jack Swigert, and Fred Haise rounding the lunar far side at 254 km pericynthion after the O2 tank #2 anomaly.', 'SPACECRAFT', 'IN_PROGRESS', (timezone('utc', now()) - interval '259200000 milliseconds'), NULL, NULL, (SELECT id FROM users WHERE email = 'elena.rodriguez@nasa.gov'), NULL, (timezone('utc', now()) - interval '3888000000 milliseconds'), (timezone('utc', now()) - interval '0 milliseconds'), NULL),
  ('mission-04', 'Apollo 17 — Taurus-Littrow Lunar Expedition', '12.6-day crewed lunar mission (Dec 7–19, 1972) with Gene Cernan, Harrison Schmitt, and Ron Evans conducting 22 h of Lunar Roving Vehicle EVA at Taurus-Littrow Valley.', 'ROVER', 'IN_PROGRESS', (timezone('utc', now()) - interval '432000000 milliseconds'), NULL, NULL, (SELECT id FROM users WHERE email = 'elena.rodriguez@nasa.gov'), NULL, (timezone('utc', now()) - interval '3888000000 milliseconds'), (timezone('utc', now()) - interval '0 milliseconds'), NULL),
  ('mission-05', 'Artemis II — Crewed Lunar Free-Return', '9-day crewed flight test aboard SLS Block 1 and Orion (Integrity) with Reid Wiseman, Victor Glover, Christina Koch, and Jeremy Hansen reaching 6,545 km above the lunar far side.', 'SPACECRAFT', 'IN_PROGRESS', (timezone('utc', now()) - interval '345600000 milliseconds'), NULL, NULL, (SELECT id FROM users WHERE email = 'elena.rodriguez@nasa.gov'), NULL, (timezone('utc', now()) - interval '3888000000 milliseconds'), (timezone('utc', now()) - interval '0 milliseconds'), NULL),
  ('mission-06', 'Apollo 8 — First Crewed Lunar Orbit', '6.1-day historic flight (Dec 21–27, 1968) with Frank Borman, Jim Lovell, and Bill Anders completing 10 lunar orbits at 111 km altitude aboard Saturn V SA-503.', 'SPACECRAFT', 'IN_PROGRESS', (timezone('utc', now()) - interval '259200000 milliseconds'), NULL, NULL, (SELECT id FROM users WHERE email = 'elena.rodriguez@nasa.gov'), NULL, (timezone('utc', now()) - interval '3888000000 milliseconds'), (timezone('utc', now()) - interval '0 milliseconds'), NULL)
