  ('seed-incident-0134', 'MEDICAL', 'heartRate', 'WARNING', 'OPEN', 'Medical alert (WARNING): Heart rate', 'Heart rate outside nominal range (47 bpm). Monitor physical activity.', 'astro-06', 'mission-05', 'HEALTH_READING', 'seed-reading-astro-06-042', 'PROTO_HEART_RATE_MONITOR', '{"indicator":"heartRate","protocolId":"PROTO_HEART_RATE_MONITOR","value":47,"readingStatus":"WARNING","seed":true}'::jsonb, (timezone('utc', now()) - interval '3692388 milliseconds'), (timezone('utc', now()) - interval '3692388 milliseconds'), (timezone('utc', now()) - interval '3692388 milliseconds'), NULL, NULL, NULL, NULL, NULL),
  ('seed-incident-rad-01', 'RADIATION', 'SOLAR_RADIATION_STORM', 'CRITICAL', 'CLOSED', 'Solar radiation storm (S2_MODERATE)', 'X1.8 flare from AR 3842 with fast CME. Crew sheltered in the Zvezda / US Lab shielded area. Abort EVA immediately.', NULL, 'mission-02', 'RADIATION_ENGINE', NULL, NULL, '{"stormScale":"S2_MODERATE","isSimulated":false,"abortEvaImmediately":true,"evacuateToStormShelter":true,"powerDownExternalSensors":false,"seed":true}'::jsonb, (timezone('utc', now()) - interval '3542400000 milliseconds'), (timezone('utc', now()) - interval '3542400000 milliseconds'), (timezone('utc', now()) - interval '3456000000 milliseconds'), (timezone('utc', now()) - interval '3541800000 milliseconds'), (SELECT id FROM users WHERE email = 'elena.rodriguez@nasa.gov'), (timezone('utc', now()) - interval '3456000000 milliseconds'), (SELECT id FROM users WHERE email = 'elena.rodriguez@nasa.gov'), 'Proton flux >10 MeV back below S1 threshold after 21 h. Crew dose within limits.'),
  ('seed-incident-rad-02', 'RADIATION', 'SOLAR_RADIATION_STORM', 'WARNING', 'CLOSED', 'Solar radiation storm (S1_MINOR)', 'M3.4 flare detected by GOES-18. Brief S1 proton event; external sensors kept powered.', NULL, 'mission-02', 'RADIATION_ENGINE', NULL, NULL, '{"stormScale":"S1_MINOR","isSimulated":false,"abortEvaImmediately":false,"evacuateToStormShelter":false,"powerDownExternalSensors":false,"seed":true}'::jsonb, (timezone('utc', now()) - interval '5875200000 milliseconds'), (timezone('utc', now()) - interval '5875200000 milliseconds'), (timezone('utc', now()) - interval '5842800000 milliseconds'), (timezone('utc', now()) - interval '5874480000 milliseconds'), (SELECT id FROM users WHERE email = 'elena.rodriguez@nasa.gov'), (timezone('utc', now()) - interval '5842800000 milliseconds'), (SELECT id FROM users WHERE email = 'elena.rodriguez@nasa.gov'), 'Event decayed below S1 after 9 h.'),
  ('seed-incident-rad-03', 'RADIATION', 'SOLAR_RADIATION_STORM', 'WARNING', 'ACKNOWLEDGED', 'Solar radiation storm (S1_MINOR)', 'M5.2 flare detected by GOES-19. Proton arrival forecast in ~45 min. Orion crew to remain in cabin.', NULL, 'mission-05', 'RADIATION_ENGINE', NULL, NULL, '{"stormScale":"S1_MINOR","isSimulated":false,"abortEvaImmediately":false,"evacuateToStormShelter":false,"powerDownExternalSensors":false,"seed":true}'::jsonb, (timezone('utc', now()) - interval '108000000 milliseconds'), (timezone('utc', now()) - interval '108000000 milliseconds'), (timezone('utc', now()) - interval '107520000 milliseconds'), (timezone('utc', now()) - interval '107520000 milliseconds'), (SELECT id FROM users WHERE email = 'elena.rodriguez@nasa.gov'), NULL, NULL, NULL),
  ('seed-incident-rad-04', 'RADIATION', 'SOLAR_RADIATION_STORM', 'CRITICAL', 'OPEN', 'Solar radiation storm (S3_STRONG)', 'X2.1 flare with SEP onset while LRV crew is on the lunar surface. Abort EVA-3 and return to LM Challenger.', NULL, 'mission-04', 'RADIATION_ENGINE', NULL, NULL, '{"stormScale":"S3_STRONG","isSimulated":true,"abortEvaImmediately":true,"evacuateToStormShelter":true,"powerDownExternalSensors":true,"seed":true}'::jsonb, (timezone('utc', now()) - interval '2700000 milliseconds'), (timezone('utc', now()) - interval '2700000 milliseconds'), (timezone('utc', now()) - interval '2700000 milliseconds'), NULL, NULL, NULL, NULL, NULL),
  ('seed-incident-mission-01', 'MISSION', 'LIFE_SUPPORT_ANOMALY', 'CRITICAL', 'ACKNOWLEDGED', 'O2 tank #2 rupture — Service Module power loss', 'Loss of O2 tank #2 and fuel cells 1 and 3. Crew transferred to LM Aquarius as lifeboat; CO2 scrubber adapter (LiOH) required.', NULL, 'mission-03', 'MISSION_CONTROL', NULL, NULL, '{"subsystem":"EPS/ECLSS","lifeboat":"LM Aquarius","seed":true}'::jsonb, (timezone('utc', now()) - interval '57600000 milliseconds'), (timezone('utc', now()) - interval '57600000 milliseconds'), (timezone('utc', now()) - interval '57420000 milliseconds'), (timezone('utc', now()) - interval '57420000 milliseconds'), (SELECT id FROM users WHERE email = 'elena.rodriguez@nasa.gov'), NULL, NULL, NULL),
  ('seed-incident-mission-02', 'MISSION', 'EVA_EQUIPMENT', 'WARNING', 'CLOSED', 'LRV right-rear fender lost — dust exposure', 'Fender extension broke off during EVA-1; crew covered in regolith. Improvised repair with maps and duct tape.', NULL, 'mission-04', 'MISSION_CONTROL', NULL, NULL, '{"subsystem":"LRV","seed":true}'::jsonb, (timezone('utc', now()) - interval '86400000 milliseconds'), (timezone('utc', now()) - interval '86400000 milliseconds'), (timezone('utc', now()) - interval '50400000 milliseconds'), (timezone('utc', now()) - interval '85800000 milliseconds'), (SELECT id FROM users WHERE email = 'elena.rodriguez@nasa.gov'), (timezone('utc', now()) - interval '50400000 milliseconds'), (SELECT id FROM users WHERE email = 'elena.rodriguez@nasa.gov'), 'Fender repaired before EVA-2.');
