  ('seed-directive-crew-01', 'astro-01', (SELECT id FROM users WHERE email = 'elena.rodriguez@nasa.gov'), NULL, 'Hydration target 3.0 L/day during translunar coast. Log fluid intake each evening.', (timezone('utc', now()) - interval '172800000 milliseconds'), (timezone('utc', now()) - interval '259200000 milliseconds'), (timezone('utc', now()) - interval '172800000 milliseconds')),
  ('seed-directive-crew-02', 'astro-09', (SELECT id FROM users WHERE email = 'elena.rodriguez@nasa.gov'), NULL, 'Schedule a private psychological conference with the BHP team and protect an 8.5 h sleep window.', NULL, (timezone('utc', now()) - interval '216000000 milliseconds'), (timezone('utc', now()) - interval '216000000 milliseconds')),
  ('seed-directive-crew-03', 'astro-10', (SELECT id FROM users WHERE email = 'elena.rodriguez@nasa.gov'), NULL, 'Keep ARED loads at prescription and add a blood pressure check 15 min after each session.', (timezone('utc', now()) - interval '3456000000 milliseconds'), (timezone('utc', now()) - interval '3463200000 milliseconds'), (timezone('utc', now()) - interval '3456000000 milliseconds')),
  ('seed-directive-crew-04', 'astro-04', (SELECT id FROM users WHERE email = 'elena.rodriguez@nasa.gov'), NULL, 'Conserve water: 200 mL every 2 h. Wear lunar overshoes and stay in LM Aquarius; staggered 4 h rest rotation.', (timezone('utc', now()) - interval '36000000 milliseconds'), (timezone('utc', now()) - interval '50400000 milliseconds'), (timezone('utc', now()) - interval '36000000 milliseconds')),
  ('seed-directive-crew-05', 'astro-11', (SELECT id FROM users WHERE email = 'elena.rodriguez@nasa.gov'), NULL, 'Report urinary symptoms and temperature every 4 h. Prioritize warm fluids when power allows.', NULL, (timezone('utc', now()) - interval '3000000 milliseconds'), (timezone('utc', now()) - interval '3000000 milliseconds')),
  ('seed-directive-crew-06', 'astro-12', (SELECT id FROM users WHERE email = 'elena.rodriguez@nasa.gov'), NULL, 'Abort EVA-3 and return to LM Challenger; log dosimeter readings at ingress.', NULL, (timezone('utc', now()) - interval '2400000 milliseconds'), (timezone('utc', now()) - interval '2400000 milliseconds')),
  ('seed-directive-crew-07', 'astro-07', (SELECT id FROM users WHERE email = 'elena.rodriguez@nasa.gov'), NULL, 'Antiemetic available in medical kit; oral rehydration 250 mL every hour until symptoms clear.', (timezone('utc', now()) - interval '216000000 milliseconds'), (timezone('utc', now()) - interval '224640000 milliseconds'), (timezone('utc', now()) - interval '216000000 milliseconds'));
