-- ============================================================================
-- OrbVital (NSA2026) — datos de prueba y estadísticas
-- Generado por backend/scripts/generateSeedSql.ts a partir de prisma/seedData.ts.
-- No editar a mano: si cambia el seed, ejecutar `npm run seed:sql`.
--
-- Uso: pegar y ejecutar completo en el SQL Editor de Supabase (o Neon), o
--   psql "$DIRECT_URL" -f prisma/seed.sql
-- Es una sola transacción: si algo falla, no se escribe nada.
-- Modo no destructivo: reemplaza solo filas con id 'seed-%' y hace upsert de
-- usuarios (por email), misiones (mission-01..06) y astronautas (astro-01..15).
-- Las fechas son relativas a now(), así que los datos quedan al día.
-- Contraseñas: elena.rodriguez@nasa.gov / HrpFlight#2026, r.wiseman@nasa.gov / OrionCrew#4IV, m.chen@nasa.gov / GroundOps#2026
-- ============================================================================

BEGIN;

-- (Opcional) Borrado total, equivalente a `prisma db seed -- --reset`.
-- Quitar los comentarios SOLO si la base tiene únicamente datos de demo.
-- SET LOCAL orbvital.allow_health_purge = 'on';
-- TRUNCATE directives, incidents, health_readings, astronauts, missions, users CASCADE;

-- health_readings es solo de agregado (trigger); el seed declara la excepción en su transacción
SET LOCAL orbvital.allow_health_purge = 'on';

DELETE FROM directives      WHERE id LIKE 'seed-%';
DELETE FROM incidents       WHERE id LIKE 'seed-%';
-- Lecturas del seed y las correcciones encadenadas a ellas (supersedesId)
CREATE TEMP TABLE seed_reading_chain ON COMMIT DROP AS
WITH RECURSIVE chain AS (
  SELECT id FROM health_readings WHERE id LIKE 'seed-%'
  UNION
  SELECT h.id FROM health_readings h JOIN chain c ON h."supersedesId" = c.id
) SELECT id FROM chain;
UPDATE health_readings SET "supersedesId" = NULL
WHERE id IN (SELECT id FROM seed_reading_chain) AND "supersedesId" IS NOT NULL;
DELETE FROM health_readings WHERE id IN (SELECT id FROM seed_reading_chain);

-- Limpiar misiones y astronautas legados que no pertenecen al seed actual
CREATE TEMP TABLE legacy_missions ON COMMIT DROP AS
SELECT id FROM missions
WHERE id NOT IN ('mission-01', 'mission-02', 'mission-03', 'mission-04', 'mission-05', 'mission-06');

CREATE TEMP TABLE legacy_astros ON COMMIT DROP AS
SELECT id FROM astronauts
WHERE id NOT IN ('astro-01', 'astro-02', 'astro-03', 'astro-04', 'astro-05', 'astro-06', 'astro-07', 'astro-08', 'astro-09', 'astro-10', 'astro-11', 'astro-12', 'astro-13', 'astro-14', 'astro-15', 'astro-16', 'astro-17', 'astro-18', 'astro-19')
   OR "missionId" IN (SELECT id FROM legacy_missions);

DELETE FROM directives WHERE "astronautId" IN (SELECT id FROM legacy_astros);
DELETE FROM incidents  WHERE "astronautId" IN (SELECT id FROM legacy_astros)
                          OR "missionId"   IN (SELECT id FROM legacy_missions);
UPDATE health_readings SET "supersedesId" = NULL
WHERE "astronautId" IN (SELECT id FROM legacy_astros) AND "supersedesId" IS NOT NULL;
DELETE FROM health_readings WHERE "astronautId" IN (SELECT id FROM legacy_astros);
DELETE FROM astronauts      WHERE id IN (SELECT id FROM legacy_astros);
DELETE FROM missions        WHERE id IN (SELECT id FROM legacy_missions);

-- Usuarios
ON CONFLICT ("email") DO UPDATE SET "name" = EXCLUDED."name", "passwordHash" = EXCLUDED."passwordHash", "role" = EXCLUDED."role", "state" = EXCLUDED."state", "updatedAt" = EXCLUDED."updatedAt", "deletedAt" = EXCLUDED."deletedAt";

-- Misiones (6)
ON CONFLICT ("id") DO UPDATE SET "name" = EXCLUDED."name", "description" = EXCLUDED."description", "environment" = EXCLUDED."environment", "status" = EXCLUDED."status", "startDate" = EXCLUDED."startDate", "endDate" = EXCLUDED."endDate", "patchUrl" = EXCLUDED."patchUrl", "operatorId" = EXCLUDED."operatorId", "updatedAt" = EXCLUDED."updatedAt", "deletedAt" = EXCLUDED."deletedAt";

-- El usuario de demo queda ligado solo a astro-01
UPDATE astronauts SET "userId" = NULL
WHERE "userId" = (SELECT id FROM users WHERE email = 'r.wiseman@nasa.gov') AND id <> 'astro-01';

-- Astronautas (19)
ON CONFLICT ("id") DO UPDATE SET "missionId" = EXCLUDED."missionId", "userId" = EXCLUDED."userId", "name" = EXCLUDED."name", "role" = EXCLUDED."role", "age" = EXCLUDED."age", "photoUrl" = EXCLUDED."photoUrl", "updatedAt" = EXCLUDED."updatedAt", "deletedAt" = EXCLUDED."deletedAt";

-- Lecturas (969; las inválidas quedan marcadas con isValid = false y su corrección apunta con supersedesId)

-- Incidentes (140)

-- Directivas (40)

COMMIT;

-- Comprobación rápida
SELECT 'health_readings' AS tabla, count(*) FROM health_readings WHERE id LIKE 'seed-%'
UNION ALL SELECT 'incidents', count(*) FROM incidents WHERE id LIKE 'seed-%'
UNION ALL SELECT 'directives', count(*) FROM directives WHERE id LIKE 'seed-%'
UNION ALL SELECT 'astronauts', count(*) FROM astronauts WHERE id LIKE 'astro-%'
UNION ALL SELECT 'missions', count(*) FROM missions WHERE id LIKE 'mission-0%';
